# WORKFLOW (Predictable control flow)
def process_ticket_workflow(ticket: TicketInput) -> TriageResult:
    if is_spam(ticket.sender):
        return TriageResult(route="spam_archive")
    category = llm_classify(ticket.body)       # Bounded LLM step
    docs = search_kb(category, ticket.body)    # Deterministic retrieval
    draft = llm_draft_reply(ticket.body, docs) # Bounded LLM step
    return TriageResult(route="human_review", draft=draft)

