from datetime import datetime, timezone

def check_refund_eligibility(purchase_date: datetime, amount_cents: int) -> dict:
    # Deterministic business logic: 100% repeatable and free
    days_since = (datetime.now(timezone.utc) - purchase_date).days
    eligible = days_since <= 30 and amount_cents <= 10000
    return {
        "eligible": eligible,
        "days_since_purchase": days_since,
        "requires_manager": amount_cents > 10000,
    }

def build_triage_plan(ticket: dict) -> dict:
    # PURE: safe to run 100x in pytest without sending emails
    category = "billing" if "invoice" in ticket["body"].lower() else "general"
    return {"category": category, "action": "create_draft", "requires_approval": True}

def execute_plan(plan: dict, approved: bool) -> str:
    # SIDE EFFECT: isolated at the boundary
    if plan["requires_approval"] and not approved:
        return "queued_for_human_review"
    # send_email(...) or update_crm(...) happens ONLY here
    return "executed"

def requires_human_approval(action_type: str, confidence: float, amount_usd: float) -> bool:
    if action_type in {"issue_refund", "delete_account", "send_external_email"}:
        return True
    if amount_usd > 0 or confidence < 0.80:
        return True
    return False  # e.g., internal read-only triage tag

import os

def load_settings() -> dict[str, str]:
    api_token = os.getenv("TRIAGE_SERVICE_TOKEN")
    if not api_token:
        raise RuntimeError("Missing required env var: TRIAGE_SERVICE_TOKEN")
    return {
        "service_token": api_token,
        "n8n_callback_url": os.getenv("N8N_CALLBACK_URL", "http://localhost:5678/webhook/callback"),
        "env": os.getenv("APP_ENV", "development"),
    }

def handle_ticket_lookup(token_claims: dict | None, requested_tenant: str) -> str:
    if token_claims is None:
        raise PermissionError("401 Unauthorized: invalid or missing credential")
    if requested_tenant not in token_claims["allowed_tenants"]:
        raise PermissionError("403 Forbidden: caller lacks access to requested tenant")
    return "Access granted"

import httpx

timeout = httpx.Timeout(connect=5.0, read=20.0, write=10.0, pool=5.0)
try:
    resp = httpx.post("http://triage-api:8000/v1/triage", json={"id": "1"}, timeout=timeout)
    resp.raise_for_status()
except httpx.ConnectTimeout:
    print("Layer 3: Firewall/routing drop or host unreachable within 5s")
except httpx.ConnectError as exc:
    print(f"Layer 1/2: DNS failed or ECONNREFUSED (wrong host/port/bind): {exc}")
except httpx.ReadTimeout:
    print("Layer 4: FastAPI accepted connection, but LLM/DB took >20s — move to async job!")

